    {
        double c[3], t[3], s;
        c[0] = mb_state.commanded_target_nms.x;
        c[1] = mb_state.commanded_target_nms.y;
        c[2] = mb_state.commanded_target_nms.z;
        t[0] = mb_config.target_nms.x;
        t[1] = mb_config.target_nms.y;
        t[2] = mb_config.target_nms.z;
        s = mb_config.target_slew_nms_per_cycle;
        for (i = 0; i < 3U; i++) {
            double d = t[i] - c[i];
            if (d > s) {
