                    (pv[i] < 0.0 && torque_i < 0.0 && pi[i] < pv[i])) {
                    pi[i] = pv[i];
                    torque_i = -kp * ev[i] - ki * pv[i];
                }
            }
            tt[i] = ADCS_CLAMP(torque_i, -tlim, tlim);
        }
        mb_state.integral_error_nms_s = (adcs_vec3_t){pi[0], pi[1], pi[2]};
